import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:plezy/services/app_icon/app_icon_catalog.dart';

/// The catalog ids are the platform names devices persist, and every asset
/// behind them is generated by scripts/codegen/generate_app_icons.py. These
/// tests fail when an id has no switchable icon on some platform, which would
/// otherwise only show up as a refused switch on a device.
void main() {
  final alternates = [
    for (final option in appIconCatalog)
      if (!option.isDefault) option.id,
  ];

  test('the default icon comes first and every id is unique', () {
    expect(appIconCatalog.first.id, defaultAppIconId);
    expect(appIconCatalog.map((option) => option.id).toSet(), hasLength(appIconCatalog.length));
    expect(alternates, hasLength(23));
  });

  // Plebz ships its own logo and none of Plezy's alternate icons: the
  // Supporter perks are compiled out (SUPPORTER_MODE off), and the aliases,
  // layers, banners, iOS/tvOS sets and picker thumbnails stay out of every
  // build. Upstream's per-alternate asset checks are translated into that.
  test('Android declares only the default .MainActivity launcher alias', () {
    final manifest = File('android/app/src/main/AndroidManifest.xml').readAsStringSync();
    expect(RegExp(r'android:name="\.appicon\.').hasMatch(manifest), isFalse);
    expect(manifest, contains('android:name=".MainActivity"'));
  });

  test('no alternate icon asset ships on any platform', () {
    const res = 'android/app/src/main/res';
    for (final id in alternates) {
      expect(File('$res/mipmap-anydpi-v26/ic_launcher_$id.xml').existsSync(), isFalse, reason: id);
      expect(File('$res/drawable-xhdpi/tv_banner_$id.webp').existsSync(), isFalse, reason: id);
    }
    expect(Directory('ios/Runner/AlternateAppIcons.xcassets').existsSync(), isFalse);
    expect(Directory('tvos/Runner/AlternateAppIcons.xcassets').existsSync(), isFalse);
    expect(Directory('assets/app_icons').existsSync(), isFalse);
  });
}
